TEST(golden_fm_textmetric_by_face_and_size){
    HDC dc = U(GetDC)(NULL);
    REQUIRE(dc);
    for (int i = 0; i < NROWS(TM); i++) {
        const tm_row *r = &TM[i];
        LOGFONTW lf; memset(&lf, 0, sizeof lf);
        lf.lfHeight = r->h; lf.lfWeight = r->wt; lf.lfItalic = (BYTE)r->it; lf.lfCharSet = (BYTE)r->cs;
        lf.lfQuality = DEFAULT_QUALITY; lf.lfOutPrecision = OUT_DEFAULT_PRECIS; lf.lfClipPrecision = CLIP_DEFAULT_PRECIS;
        lf.lfPitchAndFamily = DEFAULT_PITCH | FF_DONTCARE;
        lstrcpynW(lf.lfFaceName, r->face, LF_FACESIZE);
        HFONT f = U(CreateFontIndirectW)(&lf);
        CHECKF(f != NULL, "%s: CreateFontIndirectW failed", r->src);
        if (!f) continue;
        HGDIOBJ old = U(SelectObject)(dc, f);
        tm_compare(r->src, dc, r->got, r->th, r->ta, r->td, r->il, r->el, r->ave, r->max, r->tmwt, r->oh, r->pf, r->tmcs);
        U(SelectObject)(dc, old);
        U(DeleteObject)(f);
    }
    U(ReleaseDC)(NULL, dc);
}


TEST(golden_fm_stock_fonts){
    HDC dc = U(GetDC)(NULL);
    REQUIRE(dc);
    for (int i = 0; i < NROWS(STOCK); i++) {
        const stock_row *r = &STOCK[i];
        HGDIOBJ f = U(GetStockObject)(r->obj);
        CHECKF(f != NULL, "%s: GetStockObject failed", r->src);
        if (!f) continue;
        HGDIOBJ old = U(SelectObject)(dc, f);
        tm_compare(r->src, dc, r->got, r->th, r->ta, r->td, r->il, r->el, r->ave, r->max, r->tmwt, r->oh, r->pf, r->tmcs);
        U(SelectObject)(dc, old);
    }
    U(ReleaseDC)(NULL, dc);
}
